#!/usr/bin/env python3
import json, threading, time, base64, urllib.request, urllib.parse
from http.server import HTTPServer, BaseHTTPRequestHandler
import websocket

CDP_HTTP = 'http://127.0.0.1:9447'
LOGIN_URL = 'https://www.linkedin.com/login?fromSignIn=true'

req = urllib.request.Request(CDP_HTTP+'/json/new?url='+urllib.parse.quote(LOGIN_URL), method='PUT')
tab = json.loads(urllib.request.urlopen(req, timeout=20).read())
print('tab', tab['id'], flush=True)

ws = websocket.create_connection(tab['webSocketDebuggerUrl'], timeout=60)
_n=[0]; lock=threading.Lock(); latest_frame=[None]

def ev(method, params=None):
    _n[0]+=1
    with lock:
        ws.send(json.dumps({'id':_n[0],'method':method,'params':params or {}}))
    while True:
        m=json.loads(ws.recv())
        if m.get('id')==_n[0]:
            return m

def handle_events():
    while True:
        try:
            m=json.loads(ws.recv())
            if m.get('method')=='Page.screencastFrame':
                p=m['params']
                latest_frame[0]=p['data']
                try:
                    with lock:
                        ws.send(json.dumps({'id':900000+p['sessionId'],'method':'Page.screencastFrameAck','params':{'sessionId':p['sessionId']}}))
                except Exception: pass
        except Exception:
            time.sleep(0.2)

ev('Page.enable')
with lock:
    ws.send(json.dumps({'id':1,'method':'Page.startScreencast','params':{'format':'jpeg','quality':55,'maxWidth':1000,'maxHeight':800,'everyNthFrame':1}}))
threading.Thread(target=handle_events, daemon=True).start()

VIEWER = (open('/tmp/viewer.html').read())

class H(BaseHTTPRequestHandler):
    def log_message(self, *a): pass
    def do_GET(self):
        if self.path=='/':
            body=VIEWER.encode()
            self.send_response(200); self.send_header('content-type','text/html; charset=utf-8'); self.send_header('content-length',str(len(body))); self.end_headers()
            self.wfile.write(body)
        elif self.path=='/frame':
            body=json.dumps({'img':latest_frame[0] or ''}).encode()
            self.send_response(200); self.send_header('content-type','application/json'); self.send_header('content-length',str(len(body))); self.end_headers()
            self.wfile.write(body)
        else:
            self.send_response(404); self.end_headers()
    def do_POST(self):
        if self.path=='/input':
            ln=int(self.headers.get('content-length',0))
            data=json.loads(self.rfile.read(ln))
            a=data.get('action')
            try:
                if a=='click':
                    ev('Input.dispatchMouseEvent', {'type':'mousePressed','x':data['x'],'y':data['y'],'button':'left','clickCount':1})
                    ev('Input.dispatchMouseEvent', {'type':'mouseReleased','x':data['x'],'y':data['y'],'button':'left','clickCount':1})
                elif a=='type':
                    ev('Input.insertText', {'text':data['text']})
                elif a=='key':
                    key=data['key']; codes={'Enter':'Enter','Backspace':'Backspace','Tab':'Tab','Escape':'Escape','ArrowLeft':'ArrowLeft','ArrowRight':'ArrowRight','ArrowDown':'ArrowDown','ArrowUp':'ArrowUp'}
                    ck=codes.get(key)
                    if ck:
                        ev('Input.dispatchKeyEvent', {'type':'rawKeyDown','key':ck,'code':ck,'windowsVirtualKeyCode':({'Enter':13,'Backspace':8,'Tab':9,'Escape':27}).get(ck,0)})
                        ev('Input.dispatchKeyEvent', {'type':'keyUp','key':ck,'code':ck})
                elif a=='reload':
                    ev('Page.reload', {'ignoreCache':True})
                self.send_response(200)
            except Exception:
                self.send_response(500)
            self.end_headers()
        else:
            self.send_response(404); self.end_headers()

srv=HTTPServer(('127.0.0.1', 6080), H)
print('bridge listening 6080', flush=True)
srv.serve_forever()
